export function solve(events) {
  const seen = new Set();
  const acceptedIds = [];
  let total = 0;

  for (const { id, delta } of events) {
    if (!seen.has(id)) {
      seen.add(id);
      total += delta;
      acceptedIds.push(id);
    }
  }

  return { total, acceptedIds };
}
